//#region src/plugins/abs/core/models/JABS_Aabb.js
/**
* Axis-Aligned Bounding Box for battlers/actions in screen pixels.
* Provides common geometry helpers used by collision and overlays.
*/
var JABS_Aabb = class JABS_Aabb {
	/**
	* Constructor.
	* @param {number} x The top-left x of the rect.
	* @param {number} y The top-left y of the rect.
	* @param {number} w The width of the rect.
	* @param {number} h The height of the rect.
	*/
	constructor(x, y, w, h) {
		/**
		* The top-left x coordinate in pixels.
		* @type {number}
		*/
		this.x = x;
		/**
		* The top-left y coordinate in pixels.
		* @type {number}
		*/
		this.y = y;
		/**
		* The width in pixels.
		* @type {number}
		*/
		this.w = w;
		/**
		* The height in pixels.
		* @type {number}
		*/
		this.h = h;
		/**
		* The center x coordinate in pixels.
		* @type {number}
		*/
		this.cx = x + w / 2;
		/**
		* The center y coordinate in pixels.
		* @type {number}
		*/
		this.cy = y + h / 2;
	}
	/**
	* Builds an AABB located directly above a feet-origin point.
	* @param {number} feetX Screen-space feet x.
	* @param {number} feetY Screen-space feet y.
	* @param {number} tw Tile width.
	* @param {number} th Tile height.
	* @returns {JABS_Aabb}
	*/
	static fromFeet(feetX, feetY, tw, th) {
		const x = feetX - tw / 2;
		const y = feetY - th;
		return new JABS_Aabb(x, y, tw, th);
	}
	/**
	* Tests intersection between two rectangles.
	* @param {JABS_Aabb} other The other rect.
	* @returns {boolean} True if any overlap occurs.
	*/
	intersectsRect(other) {
		return !(other.x > this.x + this.w || other.x + other.w < this.x || other.y > this.y + this.h || other.y + other.h < this.y);
	}
	/**
	* Tests intersection of this rect vs a circle in screen pixels.
	* @param {number} cx Circle center x.
	* @param {number} cy Circle center y.
	* @param {number} r  Circle radius in pixels.
	* @returns {boolean}
	*/
	intersectsCircle(cx, cy, r) {
		const closestX = Math.max(this.x, Math.min(cx, this.x + this.w));
		const closestY = Math.max(this.y, Math.min(cy, this.y + this.h));
		const dx = cx - closestX;
		const dy = cy - closestY;
		return dx * dx + dy * dy <= r * r;
	}
	/**
	* Returns a new rect expanded by padding on all sides.
	* @param {number} padX Padding on X per side.
	* @param {number} padY Padding on Y per side.
	* @returns {JABS_Aabb}
	*/
	expanded(padX, padY) {
		return new JABS_Aabb(this.x - padX, this.y - padY, this.w + 2 * padX, this.h + 2 * padY);
	}
	/**
	* Builds a rect centered at a point with given size.
	* @param {number} cx Center x.
	* @param {number} cy Center y.
	* @param {number} w  Width.
	* @param {number} h  Height.
	* @returns {JABS_Aabb}
	*/
	static centerSized(cx, cy, w, h) {
		return new JABS_Aabb(cx - w / 2, cy - h / 2, w, h);
	}
};

//#endregion
//#region src/plugins/abs/core/models/JABS_Timer.js
/**
* A reusable timer with some nifty functions.
*/
var JABS_Timer = class {
	/**
	* Gets the timer.
	* @returns {number} The timer.
	*/
	timer() {
		return this._timer;
	}
	/**
	* Sets the timer.
	* @param {number} newTimer The new timer.
	*/
	setTimer(newTimer) {
		this._timer = newTimer;
	}
	/**
	* Gets the timer max.
	* @returns {number} The timerMax.
	*/
	timerMax() {
		return this._timerMax;
	}
	/**
	* Sets the timer max.
	* @param {number} newTimerMax The new timerMax.
	*/
	setTimerMax(newTimerMax) {
		this._timerMax = newTimerMax;
	}
	/**
	* Gets the stop counting.
	* @returns {boolean} The stopCounting.
	*/
	stopCounting() {
		return this._stopCounting;
	}
	/**
	* A key or name for this timer.
	* This is not strictly enforced by the timer, so this is for
	* developer convenience if needed.
	* @type {string}
	*/
	_key = String.empty;
	/**
	* The counter on this timer that ticks up to the max.
	* @type {number}
	*/
	_timer = 0;
	/**
	* The maximum count this timer can reach.
	* @type {number}
	*/
	_timerMax = 0;
	/**
	* Whether or not this timer has completed.
	* @type {boolean}
	*/
	_timerComplete = false;
	/**
	* Whether or not to stop counting after we've reached the max.
	* @type {boolean}
	*/
	_stopCounting = true;
	/**
	* The callback function to execute when the timer completes.
	* If none is provided, nothing will happen, though the {@link #onComplete} will still execute
	* in case you would prefer to handle it in code yourself.
	* @type {Function|null}
	*/
	_callback = null;
	/**
	* Constructor.
	*
	* NOTE: A key is not required, but can be set with setters.
	* @param {number=} timerMax The max duration of this timer.
	* @param {boolean=} stopCounting Whether or not to stop counting after completing; defaults to true.
	* @param {Function|null=} callback EXPERIMENTAL. A callback function for completion of this timer.
	*/
	constructor(timerMax = 0, stopCounting = true, callback = null) {
		this._timerMax = timerMax;
		this._stopCounting = stopCounting;
		this._callback = callback;
	}
	/**
	* Gets the key of this timer, if one was set.
	* @returns {string|String.empty}
	*/
	getKey() {
		return this._key;
	}
	/**
	* Sets the key of this timer to the given value.
	* @param {string} key The new key or name for this timer.
	*/
	setKey(key) {
		this._key = key;
	}
	/**
	* Gets the current time on this timer.
	* @returns {number}
	*/
	getCurrentTime() {
		return this.timer();
	}
	/**
	* Sets the current time of this timer to a given amount.
	* Reducing below max time will remove completion if applicable.
	* Setting at or above max time will apply completion if applicable.
	* @param {number} time The new time for this timer.
	*/
	setCurrentTime(time) {
		this.setTimer(time);
		this._handleIfIncomplete();
		this._handleIfComplete();
	}
	/**
	* Modify the current time of this timer by the given amount.
	* Reducing below max time will remove completion if applicable.
	* Setting at or above max time will apply completion if applicable.
	* @param {number} time The amount to modify by.
	* @returns {number} The new total after modification.
	*/
	modCurrentTime(time) {
		this.setTimer(this.timer() + time);
		this._handleIfIncomplete();
		this._handleIfComplete();
		return this.timer();
	}
	/**
	* Gets the total time set to run on this timer.
	* @returns {number}
	*/
	getMaxTime() {
		return this.timerMax();
	}
	/**
	* Sets the max time for this timer to the given amount.
	* @param {number} maxTime The new max time for this timer.
	*/
	setMaxTime(maxTime) {
		this.setTimerMax(maxTime);
	}
	/**
	* Whether or not we should stop counting beyond max when updating.
	* @returns {boolean}
	*/
	shouldStopCounting() {
		return this.stopCounting();
	}
	/**
	* Normalize time that is above bounds while the "stop counting" flag is set.
	*/
	normalizeTime() {
		if (!this.isTimerComplete()) return;
		if (!this.shouldStopCounting()) return;
		this.setTimer(this.getMaxTime());
	}
	/**
	* Checks whether or not this timer is completed.
	* @returns {boolean} True if it is completed, false otherwise.
	*/
	isTimerComplete() {
		return this._timerComplete;
	}
	/**
	* Resets the timer back to initial state.
	*/
	reset() {
		this.setTimer(0);
		this._timerComplete = false;
	}
	/**
	* The main update method of this timer.
	*/
	update() {
		this.tick();
		this.tock();
	}
	/**
	* Processes the incrementing of the time.
	*/
	tick() {
		if (this.isTimerComplete()) return;
		this.setTimer(this.timer() + 1);
	}
	/**
	* Processes the management of state of this timer.
	*/
	tock() {
		this._handleIfComplete();
	}
	/**
	* Handles the possibility of this timer becoming incomplete.
	*/
	_handleIfIncomplete() {
		if (this.timer() < this.timerMax()) {
			this._timerComplete = false;
		}
		this.normalizeTime();
	}
	/**
	* Handles the possibility of this timer becoming complete.
	*/
	_handleIfComplete() {
		if (this.isTimerComplete()) return;
		if (this.timer() >= this.timerMax()) {
			this._timerComplete = true;
			this.normalizeTime();
			this.onComplete();
		}
	}
	/**
	* Forcefully completes this timer.
	*/
	forceComplete() {
		this.setCurrentTime(this.getMaxTime());
		this._handleIfComplete();
	}
	onComplete() {}
};

