/**
* Extends {@link #update}.<br/>
* Also updates JABS.
*/
J.ABS.Aliased.Scene_Map.set("update", Scene_Map.prototype.update);
Scene_Map.prototype.update = function() {
	J.ABS.Aliased.Scene_Map.get("update").call(this);
	this.updateJabs();
};
/**
* Performs update logic for the JABS engine.
*/
Scene_Map.prototype.updateJabs = function() {
	if (!$jabsEngine.absEnabled) return;
	JABS_AiManager.update();
	if ($jabsEngine.requestPartyRotation) {
		this.handlePartyRotation();
	}
};
/**
* Handles the logic in the scene for a party rotation.
*/
Scene_Map.prototype.handlePartyRotation = function() {
	$jabsEngine.requestPartyRotation = false;
	this.onPartyRotate();
};
/**
* A hook for performing action when there was a party rotation request.
*/
Scene_Map.prototype.onPartyRotate = function() {};
/**
* Extends {@link #callMenu}.<br/>
* Disables the ability to directly call the menu by pressing the given key.
*
* The key vanilla listens for here is the one JABS gives to the offhand attack, and swinging a weapon
* should not open a menu. The menu has its own dedicated button, handled by
* {@link JABS_InputAdapter.performMenuAction}.
*/
J.ABS.Aliased.Scene_Map.set("callMenu", Scene_Map.prototype.callMenu);
Scene_Map.prototype.callMenu = function() {
	if ($jabsEngine.absEnabled) return;
	J.ABS.Aliased.Scene_Map.get("callMenu").call(this);
};

//#endregion
//#region src/plugins/abs/core/sprites/Sprite_Animation.js
/**
* Extends {@link Sprite_Animation.prototype.setup}.<br/>
* Normalizes Effekseer timing arrays before the engine iterates them; vanilla assumes both arrays exist and
* contain only defined timing objects, which can fail when map hits queue animations in tight succession or
* when database rows omit optional arrays.
*/
J.ABS.Aliased.Sprite_Animation.set("setup", Sprite_Animation.prototype.setup);
Sprite_Animation.prototype.setup = function(targets, animation, mirror, delay, previous) {
	if (animation === undefined || animation === null) {
		J.ABS.Aliased.Sprite_Animation.get("setup").call(this, targets, animation, mirror, delay, previous);
		return;
	}
	const hadSoundArray = Array.isArray(animation.soundTimings);
	const hadFlashArray = Array.isArray(animation.flashTimings);
	const soundTimings = hadSoundArray ? animation.soundTimings.filter((t) => t !== undefined && t !== null) : [];
	const flashTimings = hadFlashArray ? animation.flashTimings.filter((t) => t !== undefined && t !== null) : [];
	const arraysAlreadyDense = hadSoundArray && hadFlashArray && soundTimings === animation.soundTimings && flashTimings === animation.flashTimings;
	if (arraysAlreadyDense === true) {
		J.ABS.Aliased.Sprite_Animation.get("setup").call(this, targets, animation, mirror, delay, previous);
		return;
	}
	const safeAnimation = Object.assign({}, animation, {
		soundTimings,
		flashTimings
	});
	J.ABS.Aliased.Sprite_Animation.get("setup").call(this, targets, safeAnimation, mirror, delay, previous);
};
/**
* Extends {@link Sprite_Animation.prototype.targetPosition}.<br/>
* Adds a guard to ensure we don't attempt to calculate positions for destroyed sprites.
*/
J.ABS.Aliased.Sprite_Animation.set("targetPosition", Sprite_Animation.prototype.targetPosition);
Sprite_Animation.prototype.targetPosition = function(renderer) {
	if (this.animation().displayType === 2) {
		return J.ABS.Aliased.Sprite_Animation.get("targetPosition").call(this, renderer);
	}
	const validTargets = this.targets().filter((target) => target && !target.destroyed);
	if (validTargets.length === 0) {
		return new Point(0, 0);
	}
	const pos = new Point();
	for (const target of validTargets) {
		const tpos = this.targetSpritePosition(target);
		pos.x += tpos.x;
		pos.y += tpos.y;
	}
	pos.x /= validTargets.length;
	pos.y /= validTargets.length;
	return pos;
};
/**
* Extends {@link Sprite_Animation.prototype.targetSpritePosition}.<br/>
* Adds a definitive guard against null or destroyed sprites to prevent crashes during transformation updates.
* @param {Sprite} sprite The sprite to get the position of.
* @returns {Point}
*/
J.ABS.Aliased.Sprite_Animation.set("targetSpritePosition", Sprite_Animation.prototype.targetSpritePosition);
Sprite_Animation.prototype.targetSpritePosition = function(sprite) {
	if (!sprite || sprite.destroyed) {
		return new Point(0, 0);
	}
	if (sprite.character() && sprite.character().getJabsActionNeedsRemoving()) {
		return new Point(0, 0);
	}
	try {
		return J.ABS.Aliased.Sprite_Animation.get("targetSpritePosition").call(this, sprite);
	} catch {
		console.log("error happened with sprite targeting anyway: ", sprite);
		return new Point(0, 0);
	}
};

//#endregion
//#region src/plugins/abs/core/sprites/Sprite_AnimationMV.js
/**
* Extends {@link Sprite_AnimationMV.prototype.updatePosition}.<br/>
* Adds a guard to ensure we don't attempt to follow destroyed or removed sprites.
*/
J.ABS.Aliased.Sprite_AnimationMV.set("updatePosition", Sprite_AnimationMV.prototype.updatePosition);
Sprite_AnimationMV.prototype.updatePosition = function() {
	if (this.animation().position === 3) {
		J.ABS.Aliased.Sprite_AnimationMV.get("updatePosition").call(this);
		return;
	}
	const validTargets = this.targets().filter((target) => {
		if (!target || target.destroyed) return false;
		if (target.character && target.character() && target.character().getJabsActionNeedsRemoving()) {
			return false;
		}
		return true;
	});
	if (validTargets.length === 0) {
		return;
	}
	if (validTargets.length !== this.targets().length) {
		const [target] = validTargets;
		const { parent } = target;
		const grandparent = parent ? parent.parent : null;
		this.x = target.x;
		this.y = target.y;
		if (this.parent === grandparent) {
			this.x += parent.x;
			this.y += parent.y;
		}
		if (this.animation().position === 0) {
			this.y -= target.height;
		} else if (this.animation().position === 1) {
			this.y -= target.height / 2;
		}
	} else {
		J.ABS.Aliased.Sprite_AnimationMV.get("updatePosition").call(this);
	}
};

//#endregion
//#region src/plugins/abs/core/sprites/Sprite_MapCastGauge.js
/**
* A dedicated cast-time gauge for JABS battlers.
* Extends {@link Sprite_MapGauge} and binds to a {@link JABS_Battler}.
*/
var Sprite_MapCastGauge = class extends Sprite_MapGauge {
	/**
	* Gets the jabs battler.
	* @returns {JABS_Battler|null} The jabsBattler.
	*/
	jabsBattler() {
		return this._jabsBattler;
	}
	/**
	* Sets the jabs battler.
	* @param {JABS_Battler|null} newJabsBattler The new jabsBattler.
	*/
	setJabsBattler(newJabsBattler) {
		this._jabsBattler = newJabsBattler;
	}
	/**
	* Gets the expected character.
	* @returns {Game_Character|null} The expectedCharacter.
	*/
	expectedCharacter() {
		return this._expectedCharacter;
	}
	/**
	* Sets the expected character.
	* @param {Game_Character|null} newExpectedCharacter The new expectedCharacter.
	*/
	setExpectedCharacter(newExpectedCharacter) {
		this._expectedCharacter = newExpectedCharacter;
	}
	/**
	* Gets the expected uuid.
	* @returns {string|null} The expectedUuid.
	*/
	expectedUuid() {
		return this._expectedUuid;
	}
	/**
	* Sets the expected uuid.
	* @param {string|null} newExpectedUuid The new expectedUuid.
	*/
	setExpectedUuid(newExpectedUuid) {
		this._expectedUuid = newExpectedUuid;
	}
	/**
	* Gets the gauge.
	* @returns {{_bitmapWidth: number, _bitmapHeight: number, _gaugeHeight: number, _label: string,
	* _value: number|null, _iconIndex: number, _iconSprite: Sprite|null, _activated: boolean}} The gauge.
	*/
	gauge() {
		return this._gauge;
	}
	/**
	* Constructor.
	* @param {number=} bitmapWidth The bitmap width of this gauge.
	* @param {number=} bitmapHeight The bitmap height of this gauge.
	* @param {number=} gaugeHeight The height of the filled strip.
	*/
	constructor(bitmapWidth = 128, bitmapHeight = 24, gaugeHeight = 10) {
		super();
		this.initialize(bitmapWidth, bitmapHeight, gaugeHeight);
	}
	/**
	* Initializes this map cast gauge with the given parameters.
	* @param {number=} bitmapWidth The bitmap width of this gauge.
	* @param {number=} bitmapHeight The bitmap height of this gauge.
	* @param {number=} gaugeHeight The height of the filled strip.
	*/
	initialize(bitmapWidth = 128, bitmapHeight = 24, gaugeHeight = 10) {
		super.initialize(bitmapWidth, bitmapHeight, gaugeHeight);
		/**
		* The JABS battler providing cast state.
		* @type {JABS_Battler|null}
		*/
		this._jabsBattler = null;
		this.setStatusType("cast");
		this.visible = false;
	}
	/**
	* Gets the {@link JABS_Battler} this gauge is associated with.
	* @returns {JABS_Battler|null}
	*/
	getJabsBattler() {
		return this.jabsBattler();
	}
	/**
	* Binds this gauge to a JABS battler and the expected character host.
	* Also assigns the underlying Game_Battler so Sprite_Gauge internals are satisfied.
	* @param {JABS_Battler} jabsBattler The JABS battler.
	* @param {Game_Character} expectedCharacter The character this sprite represents.
	*/
	setupJabs(jabsBattler, expectedCharacter) {
		this.setJabsBattler(jabsBattler);
		/**
		* The character this gauge expects the JABS battler to be bound to.
		* (kept for reference but not used for validity gating)
		* @type {Game_Character|null}
		*/
		this.setExpectedCharacter(expectedCharacter ?? null);
		/**
		* The UUID we expect this gauge to track. Stable across leader/follower swaps.
		* @type {string}
		*/
		this.setExpectedUuid(jabsBattler ? jabsBattler.getUuid() : null);
		this.setup(jabsBattler.getBattler(), this.statusType());
	}
	/**
	* Whether the gauge should be considered valid for fill-rate.
	* Valid only while this bound JABS battler is actively casting or channeling with time left,
	* the battler identity matches the UUID we were bound to, AND the battler
	* remains bound to this sprite’s expected character.
	* @returns {boolean}
	*/
	isValid() {
		const jabsBattler = this.getJabsBattler();
		const expectedUuid = this.expectedUuid();
		const expectedCharacter = this.expectedCharacter();
		if (!jabsBattler || !expectedUuid) return false;
		if (jabsBattler.getUuid() !== expectedUuid) return false;
		if (expectedCharacter && jabsBattler.getCharacter() !== expectedCharacter) return false;
		if (!jabsBattler.isCastingOrChanneling()) return false;
		const decided = jabsBattler.getDecidedAction();
		if (!decided || decided.length === 0) return false;
		if (jabsBattler.isCasting() && jabsBattler.getCastTimeCountdown() <= 0) return false;
		if (jabsBattler.isChanneling() && jabsBattler.getChannelDurationRemaining() <= 0) return false;
		return true;
	}
	/**
	* The current value of the cast/channel bar. A cast fills up (elapsed time); a channel
	* depletes from full instead, so the two states read as visually distinct at a glance.
	* @returns {number}
	*/
	currentValue() {
		if (!this.isValid()) return NaN;
		const jabsBattler = this.getJabsBattler();
		const [action] = jabsBattler.getDecidedAction();
		if (jabsBattler.isChanneling()) {
			const [, totalDuration] = action.getBaseSkill().jabsChannel;
			if (!totalDuration) return NaN;
			return Math.max(0, jabsBattler.getChannelDurationRemaining());
		}
		const max = action.getCastTime();
		if (!max) return NaN;
		const remaining = jabsBattler.getCastTimeCountdown();
		return Math.max(0, max - remaining);
	}
	/**
	* The max value for the cast/channel bar: the action's cast time, or the channel's total
	* duration, at decision.
	* @returns {number}
	*/
	currentMaxValue() {
		if (!this.isValid()) return NaN;
		const jabsBattler = this.getJabsBattler();
		const [action] = jabsBattler.getDecidedAction();
		if (jabsBattler.isChanneling()) {
			const [, totalDuration] = action.getBaseSkill().jabsChannel;
			return totalDuration || NaN;
		}
		const max = action.getCastTime();
		return max || NaN;
	}
	/**
	* Updates this gauge.
	* Ensures the label/icon match the skill being cast while valid; otherwise clears label/icon.
	*/
	update() {
		if (this.getJabsBattler()) {
			const battler = this.getJabsBattler().getBattler();
			this.setBattler(battler);
		}
		const valid = this.isValid();
		if (valid === false) {
			this.visible = false;
			if (this.gauge()._label) {
				this.setLabel(String.empty);
			}
			if (this.gauge()._iconIndex !== -1) {
				this.setIcon(-1);
			}
			return;
		}
		this.visible = true;
		const decided = this.getJabsBattler().getDecidedAction();
		if (decided && decided.length > 0) {
			const [action] = decided;
			const skill = action.getBaseSkill();
			this.setLabel(skill.name);
			this.setIcon(skill.iconIndex >= 0 ? skill.iconIndex : -1);
		}
		super.update();
	}
	/**
	* Draws the label for the cast gauge using crisp, integer-aligned text.
	*/
	drawLabel() {
		if (!this.gauge()._label) return;
		this.bitmap.fontFace = $gameSystem.mainFontFace();
		this.bitmap.fontSize = 12;
		this.bitmap.outlineWidth = 2;
		this.bitmap.outlineColor = "rgba(0, 0, 0, 1)";
		this.bitmap.textColor = "#ffffff";
		const x = 32;
		const y = 0;
		const w = this.bitmapWidth() - x;
		const h = this.bitmapHeight();
		this.bitmap.drawText(this.gauge()._label, Math.floor(x), Math.floor(y), Math.floor(w), Math.floor(h), "left");
	}
	/**
	* Overwrites {@link Sprite_Gauge.gaugeX}.<br/>
	* Returns 0 so the fill track occupies the full bitmap width.
	* The skill name label and icon are drawn overlaid on the fill, not to its left,
	* so the track must not be shortened by the label text width.
	* @returns {number}
	*/
	gaugeX() {
		return 0;
	}
	/**
	* The background color for the cast gauge.
	* @returns {string}
	*/
	gaugeBackColor() {
		return "rgba(32, 32, 32, 0.85)";
	}
	/**
	* The left gradient color for the cast gauge.
	* @returns {string}
	*/
	gaugeColor1() {
		return "#7A5CFF";
	}
	/**
	* The right gradient color for the cast gauge.
	* @returns {string}
	*/
	gaugeColor2() {
		return "#C86BFA";
	}
};

